begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,aud,role) values
 ('11111111-1111-1111-1111-111111111111','a@example.test','authenticated','authenticated'),
 ('22222222-2222-2222-2222-222222222222','b@example.test','authenticated','authenticated');
select ok(not has_table_privilege('authenticated','clepso_private.mobile_devices','SELECT'),'tokens are not readable by clients');
select ok(not has_table_privilege('authenticated','clepso_private.mobile_devices','INSERT'),'clients cannot bypass registration lease');
select ok(not has_table_privilege('authenticated','clepso_private.mobile_device_control','UPDATE'),'clients cannot bypass device consent');
select ok(not has_function_privilege('authenticated','public.claim_mobile_signal(uuid)','EXECUTE'),'only server can claim device tokens');
select ok(not has_function_privilege('anon','public.set_mobile_device(uuid,boolean)','EXECUTE'),'anonymous cannot register devices');
select set_config('test.device','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',true);
select set_config('test.snapshot',jsonb_build_object('schemaVersion',1,'demo',false,'generatedAt',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'limits','[]'::jsonb)::text,true);
set local role authenticated;
set local request.jwt.claims='{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated"}';
select set_config('test.relay',public.set_mobile_relay(true)::text,true);
select public.publish_mobile_relay(current_setting('test.snapshot')::jsonb,current_setting('test.relay')::uuid);
select set_config('test.lease',public.set_mobile_device(current_setting('test.device')::uuid,true)::text,true);
select throws_ok($$select public.register_mobile_device(current_setting('test.device')::uuid,gen_random_uuid(),repeat('a',64),'development')$$,'42501',null,'wrong device generation denied');
select throws_ok($$select public.register_mobile_device(current_setting('test.device')::uuid,current_setting('test.lease')::uuid,'https://invalid.example/','development')$$,'22023',null,'arbitrary token string denied');
select throws_ok($$select public.register_mobile_device(current_setting('test.device')::uuid,current_setting('test.lease')::uuid,repeat('a',64),'arbitrary')$$,'22023',null,'arbitrary APNs destination denied');
select lives_ok($$select public.register_mobile_device(current_setting('test.device')::uuid,current_setting('test.lease')::uuid,repeat('a',64),'development')$$,'owner can register fixed app token');
select throws_ok($$select * from clepso_private.mobile_devices$$,'42501',null,'tokens stay private even to owner SQL role');
select throws_ok($$select * from public.claim_mobile_signal('11111111-1111-1111-1111-111111111111')$$,'42501',null,'owner cannot claim server RPC');
set local request.jwt.claims='{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated"}';
select throws_ok($$select public.register_mobile_device(current_setting('test.device')::uuid,current_setting('test.lease')::uuid,repeat('a',64),'development')$$,'42501',null,'other account cannot reuse device lease');
select set_config('test.b_lease',public.set_mobile_device(current_setting('test.device')::uuid,true)::text,true);
select public.register_mobile_device(current_setting('test.device')::uuid,current_setting('test.b_lease')::uuid,repeat('b',64),'production');
set local role service_role;
select is((select count(*)::int from public.claim_mobile_signal('22222222-2222-2222-2222-222222222222')),0,'no signal without enabled current relay');
select is((select token from public.claim_mobile_signal('11111111-1111-1111-1111-111111111111')),repeat('a',64),'server claim returns only authenticated owner device');
select is((select count(*)::int from public.claim_mobile_signal('11111111-1111-1111-1111-111111111111')),0,'account signal cooldown enforced');
set local role authenticated;
set local request.jwt.claims='{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated"}';
select public.set_mobile_device(current_setting('test.device')::uuid,false);
select throws_ok($$select public.register_mobile_device(current_setting('test.device')::uuid,current_setting('test.lease')::uuid,repeat('a',64),'development')$$,'42501',null,'late registration cannot undo off');
select set_config('test.newlease',public.set_mobile_device(current_setting('test.device')::uuid,true)::text,true);
select isnt(current_setting('test.newlease'),current_setting('test.lease'),'reenable rotates lease');
select public.register_mobile_device(current_setting('test.device')::uuid,current_setting('test.newlease')::uuid,repeat('a',64),'development');
select set_config('test.relay',public.set_mobile_relay(true)::text,true);
select public.publish_mobile_relay(current_setting('test.snapshot')::jsonb,current_setting('test.relay')::uuid);
set local role service_role;
select is((select count(*)::int from public.claim_mobile_signal('11111111-1111-1111-1111-111111111111')),0,'consent/device rotation cannot reset account cooldown');
select public.remove_invalid_mobile_device('11111111-1111-1111-1111-111111111111',current_setting('test.device')::uuid,repeat('a',64),'production');
select is((select count(*)::int from clepso_private.mobile_devices where user_id='11111111-1111-1111-1111-111111111111'),1,'old environment response cannot remove current token');
select public.remove_invalid_mobile_device('11111111-1111-1111-1111-111111111111',current_setting('test.device')::uuid,repeat('a',64),'development');
select is((select count(*)::int from clepso_private.mobile_devices where user_id='11111111-1111-1111-1111-111111111111'),0,'invalid exact token removed');
set local role authenticated;
do $$ begin for i in 1..7 loop perform public.set_mobile_device(gen_random_uuid(),true); end loop; end $$;
select throws_ok($$select public.set_mobile_device(gen_random_uuid(),true)$$,'23514',null,'device count is bounded');
select public.delete_account();
reset role;
select is((select count(*)::int from clepso_private.mobile_device_control where user_id='11111111-1111-1111-1111-111111111111'),0,'account erasure removes device leases');
select is((select count(*)::int from clepso_private.mobile_devices),1,'other account device survives');
select * from finish();
rollback;
